
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_17_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_17", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.182078784433664e+00, -5.080274739252470e+00, -4.937452515115123e+00, -4.739212904670617e+00, -4.468127937981533e+00, -4.104886352649259e+00, -3.630744701838037e+00, -3.030260349527060e+00, -2.295093607548743e+00, -1.479980135893961e+00, -8.492029973361338e-01, -6.232598531803899e-01, -6.322241285729355e-01, -5.437128933467239e-01, -3.625141981731005e-01, -1.892885942575463e-01, -7.999427754371695e-02, -2.619524065917171e-02, -5.610879704818726e-03, -6.310069655794526e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


